def add_charging_stops(instance, route):
    depot = instance.depot_id
    states = propagate_route(instance, route)
    for i, state in enumerate(states):
        if state.battery_arrival < 0:
            # Find the nearest charging station
            nearest_station = min(
                instance.station_ids,
                key=lambda sid: distance(instance.node_map[state.node_id], instance.node_map[sid]),
                default=depot
            )
            if nearest_station != depot:
                # Insert charging stop before the current node
                route.insert(i + 1, nearest_station)
                states = propagate_route(instance, route)
    return route

